CREATE OR REPLACE FUNCTION public.renewal_window_open(_status text, _start timestamptz, _end timestamptz, _cancel boolean, _now timestamptz) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN _status IN ('active','trialing') THEN _end IS NOT NULL AND _now < _end + CASE WHEN _cancel THEN interval '0 hours' ELSE interval '24 hours' END WHEN _status='past_due' THEN _start IS NOT NULL AND _now < _start + interval '24 hours' ELSE false END $$;
REVOKE ALL ON FUNCTION public.renewal_window_open(text,timestamptz,timestamptz,boolean,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.renewal_window_open(text,timestamptz,timestamptz,boolean,timestamptz) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.is_active_member(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role='admin') OR EXISTS(SELECT 1 FROM public.subscriptions WHERE profile_id=_user_id AND provider='stripe' AND stripe_environment='live' AND public.renewal_window_open(status::text,current_period_start,current_period_end,cancel_at_period_end,now())) OR EXISTS(SELECT 1 FROM public.entitlements WHERE user_id=_user_id AND source <> 'stripe' AND product_kind='app_membership' AND COALESCE(stripe_environment,'live') <> 'test' AND starts_at <= now() AND (ends_at IS NULL OR ends_at>now()) AND (status='active' OR (status='in_grace' AND grace_until>now()))); $$;
CREATE OR REPLACE FUNCTION public.billing_only_required(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public._caller_may_check(_user_id) AND NOT public.has_full_temple_access(_user_id) AND (EXISTS(SELECT 1 FROM public.subscriptions WHERE profile_id=_user_id AND provider='stripe' AND stripe_environment='live' AND (status='past_due' OR (status='active' AND NOT cancel_at_period_end AND current_period_end + interval '24 hours' <= now()))) OR EXISTS(SELECT 1 FROM public.entitlements WHERE user_id=_user_id AND source='stripe' AND stripe_environment='live' AND metadata->>'stripe_status'='unpaid')); $$;
REVOKE ALL ON FUNCTION public.billing_only_required(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.billing_only_required(uuid) TO authenticated,service_role;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='get_member_state'; def := replace(def, '''forbidden'', false', '''billing_only'', public.billing_only_required(_user_id), ''forbidden'', false'); EXECUTE def; END $$;
CREATE TABLE public.membership_checkout_locks(user_id uuid NOT NULL, environment text NOT NULL, token uuid NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(user_id,environment));
GRANT ALL ON public.membership_checkout_locks TO service_role;
ALTER TABLE public.membership_checkout_locks ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.claim_membership_checkout(_user_id uuid,_environment text,_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.membership_checkout_locks VALUES(_user_id,_environment,_token,now()+interval '2 minutes') ON CONFLICT(user_id,environment) DO UPDATE SET token=excluded.token,expires_at=excluded.expires_at WHERE membership_checkout_locks.expires_at<=now(); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.claim_membership_checkout(uuid,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_membership_checkout(uuid,text,uuid) TO service_role;
DO $$ BEGIN IF NOT public.renewal_window_open('active','2026-11-01Z','2026-11-20Z',false,'2026-11-20 23:59:59Z') OR public.renewal_window_open('active','2026-11-01Z','2026-11-20Z',false,'2026-11-21Z') OR NOT public.renewal_window_open('past_due','2026-11-20Z','2026-12-20Z',false,'2026-11-20 23:59:59Z') OR public.renewal_window_open('past_due','2026-11-20Z','2026-12-20Z',false,'2026-11-21Z') OR public.renewal_window_open('canceled','2026-11-20Z','2026-12-20Z',false,'2026-11-20Z') THEN RAISE EXCEPTION 'Renewal boundary test failed'; END IF; END $$;